#!/usr/bin/env python3
"""Code review using Claude API on pull requests."""

import os
import sys
import json
import subprocess
from pathlib import Path

import requests
from anthropic import Anthropic

GITHUB_API_URL = "https://api.github.com"
REPO = os.getenv("GITHUB_REPOSITORY")
PR_NUMBER = os.getenv("GITHUB_PR_NUMBER") or os.getenv("GITHUB_EVENT_NUMBER")
GITHUB_TOKEN = os.getenv("GITHUB_TOKEN")
ANTHROPIC_API_KEY = os.getenv("ANTHROPIC_API_KEY")

headers = {
    "Authorization": f"token {GITHUB_TOKEN}",
    "Accept": "application/vnd.github.v3+json",
}


def get_pr_diff() -> str:
    """Fetch the diff for the current PR."""
    if not PR_NUMBER:
        print("Warning: PR_NUMBER not set, skipping code review")
        return ""

    url = f"{GITHUB_API_URL}/repos/{REPO}/pulls/{PR_NUMBER}"
    resp = requests.get(url, headers=headers)
    resp.raise_for_status()

    diff_url = resp.json()["diff_url"]
    diff_resp = requests.get(diff_url, headers={**headers, "Accept": "text/plain"})
    diff_resp.raise_for_status()
    return diff_resp.text


def get_pr_details() -> dict:
    """Fetch PR title and description."""
    if not PR_NUMBER:
        return {}

    url = f"{GITHUB_API_URL}/repos/{REPO}/pulls/{PR_NUMBER}"
    resp = requests.get(url, headers=headers)
    resp.raise_for_status()
    data = resp.json()

    return {
        "title": data.get("title", ""),
        "body": data.get("body", ""),
    }


def post_review_comment(review_text: str):
    """Post code review as a PR comment."""
    if not PR_NUMBER:
        print("Warning: PR_NUMBER not set, skipping comment")
        return

    url = f"{GITHUB_API_URL}/repos/{REPO}/issues/{PR_NUMBER}/comments"
    data = {"body": review_text}
    resp = requests.post(url, json=data, headers=headers)
    resp.raise_for_status()
    print(f"Posted review comment: {resp.json()['html_url']}")


def review_code_with_claude(diff: str, pr_details: dict) -> str:
    """Use Claude to review the code changes."""
    client = Anthropic()

    context = f"""
PR Title: {pr_details.get('title', 'N/A')}
PR Description: {pr_details.get('body', 'N/A')}

Code changes (diff):
```diff
{diff}
```
"""

    message = client.messages.create(
        model="claude-haiku-4-5-20251001",
        max_tokens=1024,
        system="""You are an expert code reviewer. Analyze the provided PR diff and provide:
1. Summary of changes
2. Potential bugs or issues
3. Code quality improvements
4. Security concerns (if any)
5. Suggestions for better practices

Keep the review concise and actionable. Format as markdown.""",
        messages=[{"role": "user", "content": context}],
    )

    return message.content[0].text


def main():
    """Main function."""
    if not ANTHROPIC_API_KEY:
        print("Error: ANTHROPIC_API_KEY not set")
        sys.exit(1)

    if not GITHUB_TOKEN:
        print("Error: GITHUB_TOKEN not set")
        sys.exit(1)

    print("Fetching PR diff...")
    diff = get_pr_diff()
    if not diff:
        print("No diff found or PR_NUMBER not set")
        return

    print("Fetching PR details...")
    pr_details = get_pr_details()

    print("Running Claude code review...")
    review = review_code_with_claude(diff, pr_details)

    print("\n=== Claude Code Review ===")
    print(review)
    print("=" * 26)

    print("\nPosting review as PR comment...")
    comment_body = f"""## 🤖 Claude Code Review

{review}

---
*This review was automatically generated by Claude*"""
    post_review_comment(comment_body)


if __name__ == "__main__":
    main()
